use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn f(n: int) -> int
    recommends n >= 2
{
    if n >= 4 {
        n % 2
    } else {
        4 - n
    }
}

fn solve(queries: Vec<i8>) -> (results: Vec<i8>)
    requires
        forall |i: int| 0 <= i && i < queries.len() ==> queries[i] as int >= 2,
    ensures
        results.len() == queries.len(),
        forall |i: int| 0 <= i && i < queries.len() ==> 
            results[i] as int == f(queries[i] as int),
{
    let mut results_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < queries.len()
        invariant
            0 <= idx <= queries.len(),
            results_vec.len() == idx,
            forall |i: int| 0 <= i && i < idx ==> 
                results_vec[i] as int == f(queries[i] as int),
    {
        let query = queries[idx];
        let result: i8;
        
        proof {
            // The precondition guarantees query >= 2
            assert(query as int >= 2);
        }
        
        if query >= 4 {
            // For n >= 4: f(n) = n % 2
            // Since i8 range is -128..127, n % 2 will be 0 or 1
            result = query % 2;
        } else {
            // For 2 <= n < 4: f(n) = 4 - n
            // This gives us: f(2) = 2, f(3) = 1
            result = (4 - query) as i8;
        }
        
        results_vec.push(result);
        idx = idx + 1;
    }
    
    results_vec
}

}
